mapper.select:
SELECT 
FROM school s
WHERE s.school_code = #{schoolCode}

mapper.insert:
INSERT INTO school (
    school_code, school_name, district_code, address, contact_phone, status
) VALUES (
    #{schoolCode}, #{schoolName}, #{districtCode}, #{address}, #{contactPhone}, #{status}
)

mapper.select:
SELECT COUNT(*)
FROM school
WHERE id = #{schoolId}

mapper.update:
UPDATE sys_user u
JOIN sys_role r ON r.id = u.role_id
SET u.username = #{username},
    u.display_name = #{displayName},
    u.mobile = #{mobile},
    u.enabled = #{enabled}
    , u.password_hash = #{passwordHash}
WHERE u.id = #{id}
  AND u.school_id = #{schoolId}
  AND r.role_code = 'SCHOOL_ADMIN'

mapper.select:
SELECT 
FROM school_class c
JOIN school s ON s.id = c.school_id
WHERE c.school_id = #{schoolId}
  AND c.school_year = #{schoolYear}
  AND c.grade = #{grade}
  AND c.class_name = #{className}

mapper.update:
UPDATE school_class
SET class_name = #{className},
    grade = #{grade},
    school_year = #{schoolYear},
    status = #{status}
WHERE id = #{id}
  AND school_id = #{schoolId}
